 if(name.endsWith('/bootstrap/BrowserSession')) return {useSession(){return {session:{data:session,isError:false},transition:'idle',readPrivate:async read=>read(),commitPrivate:(commit,signal)=>{if(signal.aborted)return false;commit();return true}}}};
 if(name.endsWith('.css')) return new Proxy({},{get:(_,key)=>key==='__esModule'?false:String(key)});
