const React=req('react');
const {render,screen,within,waitFor,act,cleanup}=req('@testing-library/react');
const userEvent=req('@testing-library/user-event').default;
const {QueryClient,QueryClientProvider}=req('@tanstack/react-query');
const {MemoryRouter}=req('react-router');
const {RunPanel}=req('./src/features/engagement/RunPanel.tsx');
const {session,instance,health}=req('./tests/fixtures.ts');
const {draft,id}=req('./tests/projection-fixtures.ts');
const {syntheticRun:run,syntheticSummary:summary,inspection}=req('./tests/run-fixtures.ts');
const calls=[];
let mode='pending';let release;
const held=new Promise(resolve=>release=resolve);
global.fetch=async(input,init)=>{
 const p=String(input);calls.push({p,method:init?.method??'GET'});
 if(init?.method && init.method!=='GET') throw new Error('Non-read forbidden');
 if(p.includes('/attempts/')) {if(mode==='pending') await held; if(mode==='error') return Response.json({error:{code:'NOT_FOUND',correlation_id:id}},{status:404}); return Response.json(inspection());}
 if(p.endsWith('/summary')) return Response.json(summary);
 if(p.includes('/events?')) {const after=Number(p.split(':').at(-1));return Response.json({run_id:run.run_id,through_cursor:after,has_more:false,events:[],as_of:summary.as_of});}
 return Response.json(p==='/api/session'?session:p==='/health/ready'?health:p==='/api/instance'?instance:p===`/api/v1/engagements/${id}`?draft:p.endsWith('/run')||p==='/api/v1/runs/active'?run:null);
};
(async()=>{
 const client=new QueryClient({defaultOptions:{queries:{retry:false}}});
 const view=render(React.createElement(QueryClientProvider,{client},React.createElement(MemoryRouter,{initialEntries:[`/engagements/${id}/stream`]},React.createElement(RunPanel,{draft,stream:true}))));
 const user=userEvent.setup();
 const trigger=await screen.findByRole('button',{name:/RECON.*INCONCLUSIVE/});
 trigger.focus();await user.keyboard('{Enter}');
 await screen.findByText('Loading selected agent…');
 const dialog=screen.getByRole('dialog',{name:'Recorded agent activity'});
 console.log(JSON.stringify({scenario:'pending',dialogVisible:!!dialog,focusInside:dialog.contains(document.activeElement),focusOnTrigger:document.activeElement===trigger}));
 await user.keyboard('{Escape}');
 console.log(JSON.stringify({scenario:'pending-after-Escape',dialogStillPresent:!!screen.queryByRole('dialog',{name:'Recorded agent activity'})}));
 mode='error'; await act(async()=>{release();});
 await screen.findByText('Selected record unavailable or inconsistent. No linked result was accepted.');
 const failedDialog=screen.getByRole('dialog',{name:'Recorded agent activity'});
 console.log(JSON.stringify({scenario:'error',focusInside:failedDialog.contains(document.activeElement),focusOnTrigger:document.activeElement===trigger}));
 await user.keyboard('{Escape}');
 console.log(JSON.stringify({scenario:'error-after-Escape',dialogStillPresent:!!screen.queryByRole('dialog',{name:'Recorded agent activity'})}));
 await user.click(within(failedDialog).getByRole('button',{name:'Close inspector'}));
 console.log(JSON.stringify({scenario:'negative-control-explicit-close',closed:!screen.queryByRole('dialog',{name:'Recorded agent activity'}),restoredTrigger:document.activeElement===trigger}));
 mode='success';trigger.focus();await user.keyboard('{Enter}');
 const inspector=await screen.findByRole('region',{name:'Agent inspector'});
 await waitFor(()=>{if(document.activeElement!==within(inspector).getByRole('heading',{level:3}))throw Error('Not yet focused')});
 await user.keyboard('{Escape}');
 console.log(JSON.stringify({scenario:'negative-control-loaded',closed:!screen.queryByRole('dialog',{name:'Recorded agent activity'}),restoredTrigger:document.activeElement===trigger,nonGET:calls.filter(c=>c.method!=='GET').length}));
 view.unmount();client.clear();cleanup();dom.window.close();
})().catch(err=>{console.error(err);process.exitCode=1;dom.window.close();});
